CREATE PROCEDURE `get_atomic`(in i_project varchar(100), in i_filename varchar(100), in i_uid varchar(100))
BEGIN
	if strcmp(i_uid, "") = 0 then 
		select 
			location,
			am.model_id as uid,
			model_name,
			am.updated,
			json_data 
		from atomic_models am, projects pj
		where am.project_no=pj.pk and pj.project_name=i_project
			and am.file_name=i_filename limit 1;
	else
		select 
			location,
			am.model_id as uid,
			model_name,
			am.updated,
			json_data 
		from atomic_models am
		where model_id = i_uid limit 1;
	end if;
			
END
;;
DELIMITER ;
