CREATE PROCEDURE `get_model_list`(in i_project varchar(100))
BEGIN
	declare project_key int default 0;
	select pk into project_key from projects where project_name=i_project;
	if project_key > 0 then
		select 'c' as model_type, json_data, date_format(updated, '%Y-%m-%d %H:%i:%s') as updated from coupled_models where project_no = project_key 
		union all 
		select 'a' as model_type, json_data, date_format(updated, '%Y-%m-%d %H:%i:%s') as updated from atomic_models where project_no = project_key;
	else
		select 'project is not found';
	end if;
			
END
;;
