CREATE PROCEDURE `update_atomic`(in i_uid varchar(100), in i_project_name varchar(100), in i_model_type int(1), in i_model_name varchar(100), in i_file_name varchar(100), 
	in i_location varchar(255), in i_json_data longtext)
BEGIN
	declare _row_cnt int default 0;
	declare fk int default 0;
	declare fk2 int default 0;

	select count(pk) into fk2 from projects where project_name=i_project_name;
		if fk2 > 0 then
			select 'ok';
		else
			insert into projects(project_name, updated) 
				values(i_project_name, now());
			select 'ok';
		end if;
	
	select count(pk) into _row_cnt from atomic_models where model_id=i_uid;
	if _row_cnt > 0 then
		update atomic_models set model_name=i_model_name, model_type=i_model_type, json_data=i_json_data, location=i_location, updated=now()  where model_id=i_uid;
		select 'ok';
	else	
		select pk into fk from projects where project_name=i_project_name;
		if fk > 0 then
			insert into atomic_models(model_id, model_type, project_no, model_name, file_name, location, json_data, updated) 
				values(i_uid, i_model_type, fk, i_model_name, i_file_name, i_location, i_json_data, now());
			select 'ok';
		else
			select 'ok';
		end if;
	end if;
	commit;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
