CREATE PROCEDURE `update_coupled`(in i_uid varchar(100), in i_project_name varchar(100), in i_model_name varchar(100), in i_file_name varchar(100), 
	in i_json_data longtext)
BEGIN
	declare _row_cnt int default 0;
	declare fk int default 0;
	select count(pk) into _row_cnt from coupled_models where model_id=i_uid;
	if _row_cnt > 0 then
		update coupled_models set model_name=i_model_name, json_data=i_json_data, updated=now() where model_id=i_uid;
		select 'ok';
	else
		select pk into fk from projects where project_name=i_project_name;
		if fk > 0 then
			insert into coupled_models(model_id, project_no, model_name, file_name, json_data, updated) values(i_uid, fk, i_model_name, i_file_name, i_json_data, now());
			select 'ok';
		else
			INSERT INTO projects (project_name, updated) VALUES(i_project_name, now());
			insert into coupled_models(model_id, project_no, model_name, file_name, json_data, updated) values(i_uid, fk, i_model_name, i_file_name, i_json_data, now());
			select 'ok';
		end if;
	end if;
	commit;
END
;;
DELIMITER ;
